// @generated by:gauntlet run:godseye-local-orchestration
import { randomUUID } from "node:crypto";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { write } from "../packages/core/src/journal.js";
import { controlled } from "./helpers/agents-fixture.js";
import {
  type OrchestrationFixture,
  orchestrationFixture,
} from "./helpers/orchestration-fixture.js";

describe("immutable owner orchestration authority", () => {
  let f: OrchestrationFixture;
  beforeEach(async () => {
    f = await orchestrationFixture();
  });
  afterEach(async () => {
    await f.store.close();
  });

  it("T-AC-702 prepares frozen Hermes and coding bindings without admission", async () => {
    const coding = await f.prepareCoding();
    const key = randomUUID();
    const input = {
      ...f.input,
      steps: [
        ...f.input.steps,
        {
          id: "patch",
          dependsOn: ["research"],
          kind: "coding" as const,
          preparationId: coding.id,
          expectedHash: coding.hash,
        },
      ],
    };

    const prepared = await f.infrastructure.orchestration.prepare(f.freshOwner(), input, key);
    input.steps[0]?.dependsOn.push("patch");

    expect(prepared.state).toBe("pending");
    expect(prepared.plan.steps[0]?.step.dependsOn).toEqual([]);
    expect(prepared.plan.steps.every((step) => step.bindingHash !== null)).toBe(true);
    expect(await f.infrastructure.foundation.listRuns(f.freshOwner())).toHaveLength(0);
    expect(
      (await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id)).reservedMicros,
    ).toBe(0);
    expect(f.agentProvider.submissions).toHaveLength(0);
    expect(f.provider.submissions).toHaveLength(0);
  });

  it("T-AC-702 replays a preparation receipt but rejects changed idempotent content", async () => {
    const key = randomUUID(),
      plan = await f.prepare({}, key);
    expect(await f.prepare({}, key)).toEqual(plan);
    await expect(f.prepare({ title: "Changed intention" }, key)).rejects.toMatchObject({
      code: "IDEMPOTENCY_CONFLICT",
    });
    expect((await f.infrastructure.orchestration.overview(f.freshOwner())).plans).toHaveLength(1);
  });

  it("T-AC-703 denies service self-approval and changed exact hashes", async () => {
    const plan = await f.prepare();
    const service = {
      id: "orchestration-service",
      kind: "service" as const,
      projectIds: [f.project.id],
    };
    await expect(
      Promise.resolve().then(() =>
        f.infrastructure.orchestration.approve(
          service,
          plan.plan.id,
          { expectedHash: plan.plan.hash },
          randomUUID(),
        ),
      ),
    ).rejects.toMatchObject({ status: 403 });
    await expect(
      f.infrastructure.orchestration.approve(
        f.freshOwner(),
        plan.plan.id,
        { expectedHash: "0".repeat(64) },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 409 });
    expect((await f.detail(plan.plan.id)).state).toBe("pending");
    expect(await f.infrastructure.foundation.listRuns(f.freshOwner())).toHaveLength(0);
  });

  it("T-AC-703 requires fresh passkey assurance at approval", async () => {
    const plan = await f.prepare({ lifetimeSeconds: 3600 }),
      owner = f.freshOwner();
    f.clock.advance(300001);
    await expect(
      f.infrastructure.orchestration.approve(
        owner,
        plan.plan.id,
        { expectedHash: plan.plan.hash },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 403 });
    expect((await f.detail(plan.plan.id)).approvedBy).toBeNull();
  });

  it("T-AC-703 rechecks owner freshness after waiting for the final write transaction", async () => {
    const plan = await f.prepare({ lifetimeSeconds: 3600 });
    const entered = controlled<void>(),
      release = controlled<void>();
    const lane = write(f.store, async () => {
      entered.resolve();
      await release.promise;
    });
    await entered.promise;
    const approval = f.approve(plan);
    f.clock.advance(300001);
    release.resolve();
    await lane;
    await expect(approval).rejects.toMatchObject({ status: 403 });
    expect((await f.detail(plan.plan.id)).state).toBe("pending");
  });

  it("T-AC-703 keeps an exact owner decision idempotent and rejection terminal", async () => {
    const plan = await f.prepare(),
      key = randomUUID();
    const input = { expectedHash: plan.plan.hash };
    const rejected = await f.infrastructure.orchestration.reject(
      f.freshOwner(),
      plan.plan.id,
      input,
      key,
    );
    expect(
      await f.infrastructure.orchestration.reject(f.freshOwner(), plan.plan.id, input, key),
    ).toEqual(rejected);
    await expect(f.approve(plan)).rejects.toMatchObject({ status: 409 });
    await f.tick();
    expect(await f.infrastructure.foundation.listRuns(f.freshOwner())).toHaveLength(0);
  });

  it("T-AC-703 allows protective exact rejection after expiry with an old owner assurance", async () => {
    const plan = await f.prepare(),
      owner = f.freshOwner();
    f.clock.advance(3600001);
    const rejected = await f.infrastructure.orchestration.reject(
      owner,
      plan.plan.id,
      { expectedHash: plan.plan.hash },
      randomUUID(),
    );
    expect(rejected.state).toBe("rejected");
    expect(await f.infrastructure.foundation.listRuns(f.freshOwner())).toHaveLength(0);
  });

  it.each(["revision", "epoch", "hold", "expiry"] as const)(
    "T-AC-706 refuses approval after scope %s changes",
    async (change) => {
      const plan = await f.prepare();
      if (change === "revision")
        await f.store.db
          .update(schema.projects)
          .set({ revision: f.project.revision + 1 })
          .where(eq(schema.projects.id, f.project.id));
      if (change === "epoch")
        await f.infrastructure.foundation.advanceEpoch(
          f.freshOwner(),
          f.development.id,
          randomUUID(),
        );
      if (change === "hold")
        await f.store.db
          .update(schema.environments)
          .set({ recoveryHold: true })
          .where(eq(schema.environments.id, f.development.id));
      if (change === "expiry") f.clock.advance(300001);

      await expect(f.approve(plan)).rejects.toMatchObject({ status: 409 });
      expect(await f.infrastructure.foundation.listRuns(f.freshOwner())).toHaveLength(0);
    },
  );

  it("T-AC-704 refuses a plan below its conservative aggregate maximum", async () => {
    await expect(
      f.prepare({ maxCostMicros: f.profile.limits.maxCostMicros - 1 }),
    ).rejects.toMatchObject({ status: 409 });
    expect((await f.infrastructure.orchestration.overview(f.freshOwner())).plans).toHaveLength(0);
  });
});
